using System.Text.Json;
using JoyNect.Core.Design;
using Xunit;

namespace JoyNect.Core.Tests.Design;

/// <summary>
/// Verifies JoyNect's Material colour system against fixtures generated by the official Material
/// Color Utilities library.
/// </summary>
/// <remarks>
/// The fixtures in <c>TestData/material-color-fixtures.json</c> are produced by
/// <c>tools/color-reference/generate-fixtures.mjs</c> running Google's own implementation, not by
/// hand. Comparing against them is what makes the claim "this uses Material 3 colours" testable: if
/// the CAM16 port, the gamut solver or a tone table drifts, a specific role fails with a specific
/// delta instead of the theme quietly looking slightly wrong.
/// </remarks>
public sealed class MaterialColorTests
{
    /// <summary>
    /// One unit of slack per channel, because the reference rounds to 8 bit with a different
    /// midpoint rule in places.
    /// </summary>
    private const int ChannelTolerance = 1;

    [Fact]
    public void ReadsHueChromaAndToneLikeTheReferenceImplementation()
    {
        var problems = new List<string>();

        foreach (var palette in Fixtures().GetProperty("palettes").EnumerateArray())
        {
            var seed = ParseHex(palette.GetProperty("seed").GetString()!);
            var hct = Hct.FromArgb(seed);

            Compare(problems, $"{palette.GetProperty("seed")} hue", hct.Hue, palette.GetProperty("hue").GetDouble(), 0.05);
            Compare(problems, $"{palette.GetProperty("seed")} chroma", hct.Chroma, palette.GetProperty("chroma").GetDouble(), 0.05);
            Compare(problems, $"{palette.GetProperty("seed")} tone", hct.Tone, palette.GetProperty("tone").GetDouble(), 0.05);
        }

        FailWith(problems);
    }

    [Fact]
    public void TonalPalettesMatchTheReferenceImplementation()
    {
        var problems = new List<string>();

        foreach (var fixture in Fixtures().GetProperty("palettes").EnumerateArray())
        {
            var seed = ParseHex(fixture.GetProperty("seed").GetString()!);
            var hct = Hct.FromArgb(seed);
            var tones = fixture.GetProperty("tones").EnumerateArray().Select(t => t.GetDouble()).ToArray();

            var palettes = new Dictionary<string, TonalPalette>(StringComparer.Ordinal)
            {
                ["primary"] = new(hct.Hue, 36.0),
                ["secondary"] = new(hct.Hue, 16.0),
                ["tertiary"] = new(hct.Hue + 60.0, 24.0),
                ["neutral"] = new(hct.Hue, 6.0),
                ["neutralVariant"] = new(hct.Hue, 8.0),
                ["error"] = new(25.0, 84.0),
            };

            foreach (var (name, palette) in palettes)
            {
                var expected = fixture.GetProperty(name).EnumerateArray().Select(e => ParseHex(e.GetString()!)).ToArray();

                for (var i = 0; i < tones.Length && i < expected.Length; i++)
                {
                    CompareColour(
                        problems,
                        $"{name} tone {tones[i]:0.##}",
                        palette.Tone(tones[i]),
                        expected[i]);
                }
            }
        }

        FailWith(problems);
    }

    [Fact]
    public void SchemesMatchTheReferenceImplementation()
    {
        var problems = new List<string>();
        var checkedRoles = 0;

        foreach (var fixture in Fixtures().GetProperty("schemes").EnumerateArray())
        {
            var seed = ParseHex(fixture.GetProperty("seed").GetString()!);
            var isDark = fixture.GetProperty("dark").GetBoolean();
            var variant = fixture.GetProperty("scheme").GetString() == "expressive"
                ? SchemeVariant.Expressive
                : SchemeVariant.TonalSpot;

            var scheme = MaterialSchemes.Create(seed, isDark, variant);
            var label = $"{fixture.GetProperty("seed")} {variant} dark={isDark}";

            foreach (var role in fixture.GetProperty("roles").EnumerateObject())
            {
                var mapped = ColorRoleInfoTable.FromKey(role.Name);
                Assert.NotNull(mapped);

                CompareColour(problems, $"{label} {role.Name}", scheme[mapped!.Value], ParseHex(role.Value.GetString()!));
                checkedRoles++;
            }
        }

        FailWith(problems);

        // Sanity check that the fixture really was exercised rather than silently empty.
        Assert.True(checkedRoles >= 700, $"only {checkedRoles} role comparisons ran");
    }

    [Theory]
    [InlineData(SchemeVariant.TonalSpot)]
    [InlineData(SchemeVariant.Expressive)]
    public void EveryThemeKeepsTextLegible(SchemeVariant variant)
    {
        var problems = new List<string>();

        foreach (var seed in Seeds())
        {
            foreach (var isDark in new[] { false, true })
            {
                var scheme = MaterialSchemes.Create(seed, isDark, variant);

                AssertPair(problems, scheme, ColorRole.OnSurface, ColorRole.Surface, 4.5, "body text on a surface");
                AssertPair(problems, scheme, ColorRole.OnSurfaceVariant, ColorRole.Surface, 4.5, "secondary text on a surface");
                AssertPair(problems, scheme, ColorRole.OnSurface, ColorRole.SurfaceContainerHigh, 4.5, "body text on a raised card");
                AssertPair(problems, scheme, ColorRole.OnPrimary, ColorRole.Primary, 4.5, "label on a filled button");
                AssertPair(problems, scheme, ColorRole.OnPrimaryContainer, ColorRole.PrimaryContainer, 4.5, "label in a tonal container");
                AssertPair(problems, scheme, ColorRole.OnSecondaryContainer, ColorRole.SecondaryContainer, 4.5, "label in a secondary container");
                AssertPair(problems, scheme, ColorRole.OnTertiaryContainer, ColorRole.TertiaryContainer, 4.5, "label in a tertiary container");
                AssertPair(problems, scheme, ColorRole.OnErrorContainer, ColorRole.ErrorContainer, 4.5, "label in an error container");
                AssertPair(problems, scheme, ColorRole.OnError, ColorRole.Error, 4.5, "label on an error fill");
                AssertPair(problems, scheme, ColorRole.InverseOnSurface, ColorRole.InverseSurface, 4.5, "text on an inverse surface");
            }
        }

        Assert.Empty(problems);
    }

    [Fact]
    public void HighContrastModeMeetsAaaForText()
    {
        var problems = new List<string>();

        foreach (var seed in Seeds())
        {
            foreach (var isDark in new[] { false, true })
            {
                var scheme = MaterialSchemes.Create(seed, isDark, SchemeVariant.Expressive, ContrastLevel.High);

                AssertPair(problems, scheme, ColorRole.OnSurface, ColorRole.Surface, 7.0, "body text on a surface");
                AssertPair(problems, scheme, ColorRole.OnSurfaceVariant, ColorRole.Surface, 7.0, "secondary text on a surface");
                AssertPair(problems, scheme, ColorRole.OnSurface, ColorRole.SurfaceContainerHigh, 7.0, "body text on a raised card");
                AssertPair(problems, scheme, ColorRole.OnPrimaryContainer, ColorRole.PrimaryContainer, 7.0, "label in a tonal container");
                AssertPair(problems, scheme, ColorRole.Outline, ColorRole.Surface, 4.5, "outline against a surface");
            }
        }

        Assert.Empty(problems);
    }

    [Fact]
    public void HighContrastIsAtLeastAsReadableAsTheStandardScheme()
    {
        foreach (var seed in Seeds())
        {
            foreach (var isDark in new[] { false, true })
            {
                var standard = MaterialSchemes.Create(seed, isDark, SchemeVariant.Expressive);
                var high = MaterialSchemes.Create(seed, isDark, SchemeVariant.Expressive, ContrastLevel.High);

                var standardRatio = ColorUtils.ContrastRatio(standard.OnSurface, standard.Surface);
                var highRatio = ColorUtils.ContrastRatio(high.OnSurface, high.Surface);

                Assert.True(
                    highRatio >= standardRatio,
                    $"high contrast text ratio {highRatio:F2} was below the standard ratio {standardRatio:F2} for {ColorUtils.ToHex(seed)}");
            }
        }
    }

    [Fact]
    public void FixedRolesDoNotChangeBetweenModes()
    {
        var scheme = MaterialSchemes.Create(MaterialSchemes.BaselineSeed, isDark: false, SchemeVariant.Expressive);
        var dark = scheme.WithMode(true);

        foreach (var role in new[] { ColorRole.PrimaryFixed, ColorRole.PrimaryFixedDim, ColorRole.OnPrimaryFixed, ColorRole.OnPrimaryFixedVariant })
        {
            Assert.Equal(scheme[role], dark[role]);
        }
    }

    [Fact]
    public void ChangingModeRecomputesOnlyTheModeDependentRoles()
    {
        var scheme = MaterialSchemes.Create(MaterialSchemes.BaselineSeed, isDark: false, SchemeVariant.TonalSpot);
        var dark = scheme.WithMode(true);

        Assert.Equal(scheme.PrimaryPalette.Hue, dark.PrimaryPalette.Hue, 3);
        Assert.NotEqual(scheme.Surface, dark.Surface);
        Assert.NotEqual(scheme.OnSurface, dark.OnSurface);
        Assert.NotEqual(scheme.Primary, dark.Primary);
    }

    [Fact]
    public void EveryRoleIsDistinctWhereItShouldBe()
    {
        var scheme = MaterialSchemes.Create(MaterialSchemes.BaselineSeed, isDark: false, SchemeVariant.Expressive);

        // A container must be able to hold its content legibly, which is only possible if it is not
        // the same colour as the fill it sits on.
        Assert.NotEqual(scheme.Primary, scheme.PrimaryContainer);
        Assert.NotEqual(scheme.Surface, scheme.SurfaceContainer);

        // The surface ramp must be ordered, or nested layers would look inverted.
        Assert.True(ColorUtils.LstarFromArgb(scheme.SurfaceContainerLowest) >= ColorUtils.LstarFromArgb(scheme.SurfaceContainerLow));
        Assert.True(ColorUtils.LstarFromArgb(scheme.SurfaceContainerLow) >= ColorUtils.LstarFromArgb(scheme.SurfaceContainer));
        Assert.True(ColorUtils.LstarFromArgb(scheme.SurfaceContainer) >= ColorUtils.LstarFromArgb(scheme.SurfaceContainerHighest));
    }

    [Fact]
    public void PaletteTonesPreserveTheirToneAndHue()
    {
        var palette = new TonalPalette(252.0, 40.0);

        foreach (var tone in new[] { 10.0, 20.0, 40.0, 60.0, 80.0, 90.0 })
        {
            var colour = Hct.FromArgb(palette.Tone(tone));

            Assert.InRange(colour.Tone, tone - 0.5, tone + 0.5);

            // Very light and very dark tones cannot carry much chroma, but the hue must not drift.
            if (colour.Chroma > 5.0)
            {
                Assert.InRange(AngleDistance(colour.Hue, palette.Hue), 0.0, 2.0);
            }
        }
    }

    [Fact]
    public void GreyPalettesStayGrey()
    {
        var palette = new TonalPalette(120.0, 0.0);

        foreach (var tone in new[] { 20.0, 50.0, 80.0 })
        {
            // A grey palette must produce actual greys. CAM16 reports a small chroma for them (the
            // D65 adaptation is not perfect), so the invariant worth asserting is on the pixels.
            var colour = palette.Tone(tone);
            Assert.InRange(Math.Abs(ColorUtils.RedFromArgb(colour) - ColorUtils.GreenFromArgb(colour)), 0, 1);
            Assert.InRange(Math.Abs(ColorUtils.GreenFromArgb(colour) - ColorUtils.BlueFromArgb(colour)), 0, 1);
        }
    }

    [Theory]
    [InlineData("#6750A4", 0xFF6750A4u)]
    [InlineData("6750A4", 0xFF6750A4u)]
    [InlineData("#FF6750A4", 0xFF6750A4u)]
    public void ParsesHexColours(string text, uint expected)
    {
        Assert.True(ColorUtils.TryParseHex(text, out var parsed));
        Assert.Equal(expected, parsed);
    }

    [Theory]
    [InlineData("")]
    [InlineData("#12")]
    [InlineData("not a colour")]
    [InlineData("#GGGGGG")]
    public void RejectsInvalidHexColours(string text)
    {
        Assert.False(ColorUtils.TryParseHex(text, out _));
    }

    [Fact]
    public void FormatsHexColours()
    {
        Assert.Equal("#6750A4", ColorUtils.ToHex(0xFF6750A4));
    }

    [Fact]
    public void CriticalPlanesMatchTheReferenceTable()
    {
        // Sampled from the reference implementation: one value in the linear segment, one at a
        // segment boundary and one in the gamma segment. The solver's table is generated rather than
        // copied, so these values guard the generation.
        Assert.Equal(0.015176349177441876, ColorUtils.Linearized(0.5), 12);
        Assert.Equal(0.045529047532325624, ColorUtils.Linearized(1.5), 12);
        Assert.Equal(99.55452497210776, ColorUtils.Linearized(254.5), 10);
    }

    /// <summary>Fails with the first few mismatches in readable form.</summary>
    /// <remarks>
    /// A bare <c>Assert.Empty</c> on a long list prints one truncated line, which hides exactly the
    /// information needed to fix a colour regression.
    /// </remarks>
    private static void FailWith(List<string> problems)
    {
        Assert.True(
            problems.Count == 0,
            $"{problems.Count} mismatch(es):{Environment.NewLine}{string.Join(Environment.NewLine, problems.Take(12))}");
    }

    private static double AngleDistance(double a, double b)
    {
        var difference = Math.Abs(a - b) % 360.0;
        return difference > 180.0 ? 360.0 - difference : difference;
    }

    private static void AssertPair(
        List<string> problems,
        M3Scheme scheme,
        ColorRole foreground,
        ColorRole background,
        double minimumRatio,
        string description)
    {
        var ratio = ColorUtils.ContrastRatio(scheme[foreground], scheme[background]);
        if (ratio < minimumRatio)
        {
            problems.Add(
                $"{description}: {ColorUtils.ToHex(scheme[foreground])} on {ColorUtils.ToHex(scheme[background])} is {ratio:F2}:1, want {minimumRatio:F1}:1");
        }
    }

    private static void Compare(List<string> problems, string label, double actual, double expected, double tolerance)
    {
        if (Math.Abs(actual - expected) > tolerance)
        {
            problems.Add($"{label}: got {actual:F4}, want {expected:F4}");
        }
    }

    private static void CompareColour(List<string> problems, string label, uint actual, uint expected)
    {
        var worst = Math.Max(
            Math.Abs(ColorUtils.RedFromArgb(actual) - ColorUtils.RedFromArgb(expected)),
            Math.Max(
                Math.Abs(ColorUtils.GreenFromArgb(actual) - ColorUtils.GreenFromArgb(expected)),
                Math.Abs(ColorUtils.BlueFromArgb(actual) - ColorUtils.BlueFromArgb(expected))));

        if (worst > ChannelTolerance)
        {
            problems.Add($"{label}: got {ColorUtils.ToHex(actual)}, want {ColorUtils.ToHex(expected)} (off by {worst})");
        }
    }

    private static uint ParseHex(string text)
    {
        Assert.True(ColorUtils.TryParseHex(text, out var argb), $"could not parse {text}");
        return argb;
    }

    private static readonly string[] SeedHexes = ["#6750A4", "#B3261E", "#2E7D32", "#0B6C8F"];

    private static IEnumerable<uint> Seeds() => SeedHexes.Select(ParseHex);

    private static JsonElement Fixtures() => FixtureDocument.Value;

    private static readonly Lazy<JsonElement> FixtureDocument = new(() =>
    {
        var path = Path.Combine(AppContext.BaseDirectory, "TestData", "material-color-fixtures.json");
        Assert.True(File.Exists(path), $"fixture missing at {path}; run tools/color-reference/generate-fixtures.mjs");
        using var document = JsonDocument.Parse(File.ReadAllText(path));
        return document.RootElement.Clone();
    });
}
